'use strict';
// Vanilla adaptation of countup.txt: per-digit sliding, stable width, no React runtime.
(()=>{const previous=new Map(),format=n=>new Intl.NumberFormat('vi-VN').format(n);function mount(root=document){for(const el of root.querySelectorAll('[data-count-to]')){const to=Math.max(0,Math.round(Number(el.dataset.countTo)||0)),key=el.dataset.countId||'',old=previous.get(key)??0;if(el.dataset.countPainted===String(to))continue;el.dataset.countPainted=String(to);previous.set(key,to);el.setAttribute('aria-label',format(to));el.style.fontVariantNumeric='tabular-nums';const target=format(to),before=format(old).padStart(target.length,'0');el.replaceChildren();[...target].forEach((ch,i)=>{const slot=document.createElement('span');slot.setAttribute('aria-hidden','true');if(!/\d/.test(ch)){slot.textContent=ch;el.append(slot);return;}slot.style.cssText='display:inline-block;position:relative;width:.68em;height:1.08em;overflow:hidden;vertical-align:bottom';const track=document.createElement('span');track.style.cssText='position:absolute;left:0;top:0;display:grid;line-height:1.08em;will-change:transform';for(let n=0;n<10;n++){const digit=document.createElement('span');digit.textContent=n;digit.style.cssText='height:1.08em;text-align:center';track.append(digit);}const from=/\d/.test(before[i])?Number(before[i]):0;track.style.transform=`translateY(${-from*10}%)`;slot.append(track);el.append(slot);requestAnimationFrame(()=>{if(!slot.isConnected)return;track.style.transition=matchMedia('(prefers-reduced-motion: reduce)').matches?'none':'transform 650ms cubic-bezier(.22,1,.36,1)';track.style.transform=`translateY(${-Number(ch)*10}%)`;});});}}window.KienCountUp={mount};})();
